import { Button } from "@/registry/erbium/ui/button";
import { ButtonGroup } from "@/registry/erbium/ui/button-group";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { Input } from "@/registry/erbium/ui/input";

export function InputButtonGroup() {
  return (
    <Field>
      <FieldLabel>Search</FieldLabel>
      <ButtonGroup>
        <Input placeholder="Type to search..." />
        <Button variant="outline">Search</Button>
      </ButtonGroup>
    </Field>
  );
}

import { InputButtonGroup } from "../examples/upstream/input-button-group";

const Example = () => <InputButtonGroup />;

export default Example;
